initJs:
function(container, apiUrl, tables) {
  let isProcessing = false;
  let predictionResults = [];

  // 店舗データとカテゴリデータの取得
  const storeTable = tables.find(t => t.tableName === '店舗マスタ');
  const productTable = tables.find(t => t.tableName === '商品マスタ');

  // 店舗選択肢の設定
  function setupStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリチェックボックスの設定
  function setupCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    // 商品マスタから商品カテゴリIDを抽出してユニークなカテゴリを作成
    const categories = new Set();
    if (productTable && productTable.records) {
      productTable.records.forEach(product => {
        if (product.商品カテゴリID) {
          categories.add(product.商品カテゴリID);
        }
      });
    }

    // デフォルトカテゴリを追加
    const defaultCategories = ['食品', '日用品', '衣料品', '家電', '書籍', '化粧品'];
    defaultCategories.forEach(cat => categories.add(cat));

    categories.forEach(categoryId => {
      const label = document.createElement('label');
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = categoryId;
      checkbox.name = 'product-categories';

      label.appendChild(checkbox);
      label.appendChild(document.createTextNode(categoryId));
      categoryContainer.appendChild(label);
    });
  }

  // 季節要因スライダーの値表示更新
  function setupSeasonalSlider() {
    const slider = container.querySelector('#seasonal-factor');
    const valueDisplay = container.querySelector('#seasonal-value');

    slider.addEventListener('input', function() {
      valueDisplay.textContent = this.value;
    });
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const startDate = container.querySelector('#prediction-start-date').value;
    const endDate = container.querySelector('#prediction-end-date').value;
    const storeSelect = container.querySelector('#store-select');
    const selectedStores = Array.from(storeSelect.selectedOptions);
    const selectedCategories = container.querySelectorAll('input[name="product-categories"]:checked');
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStartDate = container.querySelector('#learning-start-date').value;
    const learningEndDate = container.querySelector('#learning-end-date').value;

    if (!startDate) {
      errors.push('予測対象期間の開始日を入力してください');
    }

    if (!endDate) {
      errors.push('予測対象期間の終了日を入力してください');
    }

    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (start < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      if (end < start) {
        errors.push('予測期間の終了日は開始日以降を指定してください');
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    if (selectedStores.length === 0) {
      errors.push('店舗を選択してください');
    }

    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    if (!learningStartDate) {
      errors.push('学習データ期間の開始日を入力してください');
    }

    if (!learningEndDate) {
      errors.push('学習データ期間の終了日を入力してください');
    }

    if (learningStartDate && learningEndDate && startDate && endDate) {
      const learningStart = new Date(learningStartDate);
      const learningEnd = new Date(learningEndDate);
      const predictionStart = new Date(startDate);
      const predictionEnd = new Date(endDate);

      const learningPeriod = Math.ceil((learningEnd - learningStart) / (1000 * 60 * 60 * 24));
      const predictionPeriod = Math.ceil((predictionEnd - predictionStart) / (1000 * 60 * 60 * 24));

      if (learningPeriod < predictionPeriod) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorContainer = container.querySelector('#error-messages');
    if (errors.length > 0) {
      errorContainer.innerHTML = '<h4>入力エラー</h4><ul>' + 
        errors.map(error => `<li>${error}</li>`).join('') + '</ul>';
      errorContainer.classList.remove('hidden');
    } else {
      errorContainer.classList.add('hidden');
    }
  }

  // 進捗バー更新
  function updateProgress(percentage, message) {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');

    progressFill.style.width = percentage + '%';
    progressText.textContent = message;
  }

  // UI無効化/有効化
  function setUIEnabled(enabled) {
    const inputs = container.querySelectorAll('input, select, button');
    inputs.forEach(input => {
      input.disabled = !enabled;
    });

    if (!enabled) {
      container.querySelector('#progress-section').classList.remove('hidden');
    } else {
      container.querySelector('#progress-section').classList.add('hidden');
    }
  }

  // 天候データ取込
  async function importWeatherData() {
    try {
      container.querySelector('#weather-status').textContent = '取込中...';

      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 実際の実装では weather API を呼び出し
      const weatherData = {
        店舗ID: 'dummy-store-id',
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 18,
        平均気温: 22,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '予報値',
        データソース: '気象庁API'
      };

      const weatherTableIndex = tables.findIndex(t => t.tableName === '天候データ');
      if (weatherTableIndex >= 0) {
        await window.aivicApi.save(weatherTableIndex, weatherData);
        container.querySelector('#weather-status').textContent = '取込完了';
      } else {
        throw new Error('天候データテーブルが見つかりません');
      }

    } catch (error) {
      container.querySelector('#weather-status').textContent = '取込失敗';
      showErrors(['天候データの取得に失敗しました。データソースの設定を確認してください。']);
    }
  }

  // イベントデータ取込
  async function importEventData() {
    try {
      container.querySelector('#events-status').textContent = '取込中...';

      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));

      const eventData = {
        店舗ID: 'dummy-store-id',
        イベント名: 'サンプルイベント',
        イベント種別: 'セール',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        予想来場者数: 1000,
        影響度: '中',
        場所: '店舗周辺',
        店舗からの距離: 500,
        有効フラグ: true
      };

      const eventTableIndex = tables.findIndex(t => t.tableName === 'イベントデータ');
      if (eventTableIndex >= 0) {
        await window.aivicApi.save(eventTableIndex, eventData);
        container.querySelector('#events-status').textContent = '取込完了';
      } else {
        throw new Error('イベントデータテーブルが見つかりません');
      }

    } catch (error) {
      container.querySelector('#events-status').textContent = '取込失敗';
      showErrors(['イベントデータの取込に失敗しました。ファイル形式を確認してください。']);
    }
  }

  // AI予測実行
  async function executePrediction() {
    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return;
    }

    showErrors([]);
    isProcessing = true;
    setUIEnabled(false);

    try {
      // 進捗更新のシミュレーション
      const progressSteps = [
        { percentage: 10, message: 'データ収集中...' },
        { percentage: 30, message: '外部要因データを分析中...' },
        { percentage: 50, message: 'AIモデルを学習中...' },
        { percentage: 70, message: '需要予測を計算中...' },
        { percentage: 90, message: '結果を生成中...' },
        { percentage: 100, message: '処理完了' }
      ];

      for (const step of progressSteps) {
        updateProgress(step.percentage, step.message);
        await new Promise(resolve => setTimeout(resolve, 1000));
      }

      // 予測結果の生成（模擬データ）
      const selectedStores = Array.from(container.querySelector('#store-select').selectedOptions);
      const selectedCategories = Array.from(container.querySelectorAll('input[name="product-categories"]:checked'));
      const startDate = new Date(container.querySelector('#prediction-start-date').value);
      const endDate = new Date(container.querySelector('#prediction-end-date').value);

      predictionResults = [];

      selectedStores.forEach(storeOption => {
        selectedCategories.forEach(categoryCheckbox => {
          for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
            const result = {
              予測結果ID: crypto.randomUUID(),
              店舗ID: storeOption.value,
              店舗名: storeOption.textContent,
              商品カテゴリ: categoryCheckbox.value,
              予測対象日: new Date(d).toISOString().split('T')[0],
              予測数量: Math.floor(Math.random() * 100) + 50,
              予測精度: Math.floor(Math.random() * 30) + 70,
              推奨発注数量: Math.floor(Math.random() * 80) + 40,
              予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
              予測ステータス: '完了',
              発注済フラグ: false
            };
            predictionResults.push(result);
          }
        });
      });

      // 結果をデータベースに保存
      const resultTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');
      if (resultTableIndex >= 0) {
        for (const result of predictionResults) {
          await window.aivicApi.save(resultTableIndex, result);
        }
      }

      // 結果表示
      renderPredictionResults();
      container.querySelector('#prediction-results').classList.remove('hidden');

    } catch (error) {
      showErrors(['AI予測実行が失敗しました: ' + error.message]);
    } finally {
      isProcessing = false;
      setUIEnabled(true);
    }
  }

  // 予測結果の表示
  function renderPredictionResults() {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = predictionResults.map(result => `
      <tr data-id="${result.予測結果ID}">
        <td>${result.店舗名}</td>
        <td>${result.商品カテゴリ}</td>
        <td>${result.予測対象日}</td>
        <td>${result.予測数量}</td>
        <td>${result.予測精度}%</td>
        <td>${result.推奨発注数量}</td>
        <td>
          <button class="action-btn secondary order-btn" data-id="${result.予測結果ID}">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // CSVエクスポート
  function exportResultsToCSV() {
    if (predictionResults.length === 0) {
      alert('エクスポートする結果がありません');
      return;
    }

    const headers = ['店舗名', '商品カテゴリ', '予測日', '予測数量', '予測精度', '推奨発注数量'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      predictionResults.map(result => [
        result.店舗名,
        result.商品カテゴリ,
        result.予測対象日,
        result.予測数量,
        result.予測精度 + '%',
        result.推奨発注数量
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'ai_prediction_results_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  }

  // 初期化処理
  setupStoreOptions();
  setupCategoryCheckboxes();
  setupSeasonalSlider();

  // デフォルト日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);
  const lastMonth = new Date(today);
  lastMonth.setMonth(lastMonth.getMonth() - 1);

  container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
  container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];

  // イベントリスナー設定
  container.querySelector('#btn-import-weather').addEventListener('click', importWeatherData);
  container.querySelector('#btn-import-events').addEventListener('click', importEventData);
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-export-results').addEventListener('click', exportResultsToCSV);
  container.querySelector('#btn-goto-order').addEventListener('click', () => {
    window.showScreen('scr-1778591852463'); // 発注管理画面
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const resultId = orderBtn.dataset.id;
      const result = predictionResults.find(r => r.予測結果ID === resultId);
      if (result && confirm(`${result.店舗名}の${result.商品カテゴリ}について発注処理を実行しますか？`)) {
        // 発注データ作成
        const orderData = {
          店舗ID: result.店舗ID,
          商品ID: 'dummy-product-id', // 実際は商品マスタから取得
          需要予測結果ID: result.予測結果ID,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
          発注数量: result.推奨発注数量,
          予測数量: result.予測数量,
          発注単価: 100, // 仮の単価
          発注金額: result.推奨発注数量 * 100,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'dummy-supplier-id',
          発注理由: 'AI需要予測に基づく自動発注',
          自動発注フラグ: true
        };

        const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
        if (orderTableIndex >= 0) {
          const saved = await window.aivicApi.save(orderTableIndex, orderData);
          if (saved) {
            alert('発注処理が完了しました');
            // 発注済フラグを更新
            result.発注済フラグ = true;
            renderPredictionResults();
          }
        }
      }
    }
  });
}
